const f=load("finalFocused");
const expected=encodeURIComponent(JSON.stringify({continuation:f.production.continuation,selection_hash:f.hash,requirements_hash:f.requirements_hash,state_hash:f.production.hash})).replace(/'/g,"%27");
const script=`import json,pathlib,hashlib,urllib.parse
root=pathlib.Path.cwd()
expected=json.loads(urllib.parse.unquote("${expected}"))
def read(p): return json.loads(pathlib.Path(p).read_text(encoding="utf-8"))
def ident(p): return {"path":p,"sha256":hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()}
hp=".pixl/handoffs/471ca3bdab500660dcfdee267410d83605e0d554af01d24ca24213daf7181042.json"
h=read(hp)
baseline=read("work/queue.ready-handoff/preservation-baseline.json")
changed=[p for p,digest in baseline.items() if not pathlib.Path(p).is_file() or hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()!=digest]
links=h["details"]["artifacts"]+[h["details"]["caller_actions"][0]["evidence"]]
bad_links=[v["path"] for v in links if ident(v["path"])["sha256"]!=v["sha256"]]
checks={"exact_resume_matches_fresh_focused_plar":h["resume"]==expected["continuation"],"selection_hash_matches":h["selection"]["hash"]==expected["selection_hash"],"requirements_hash_matches":h["requirements_hash"]==expected["requirements_hash"],"state_hash_matches":h["resume"]["state_hash"]==expected["state_hash"],"handoff_hash_matches_filename":ident(hp)["sha256"]==pathlib.Path(hp).stem,"linked_artifacts_verified":not bad_links,"historical_files_unchanged":not changed}
assert all(checks.values()),(checks,changed,bad_links)
comparison={"version":1,"reviewer_role":"independent calling agent /root","status":"consistent","handoff":ident(hp),"checks":checks,"historical_files_compared":len(baseline),"changed_historical_files":changed,"interpretation":"Exact runtime review_delivery remains unchanged. Caller review and source consumption are complete for PHASE; this does not authorize another request or complete family/style/renderer acceptance.","contract_comparison":ident("work/queue.ready-handoff/caller-review.json"),"future_work":h["details"]["future_work"]}
cp="work/queue.ready-handoff/handoff-comparison.json"
pathlib.Path(cp).write_text(json.dumps(comparison,indent=2)+"\\n",encoding="utf-8")
result={"version":1,"status":"delivered","assignment":"PHASE.md retained contract reassessment and exact handoff","specialist":{"native_agent":"/root/pixl_specialist","installed_skill":".agents/skills/pixl-kit/skills/pixl/SKILL.md"},"handoff":ident(hp),"independent_comparison":ident(cp),"independent_contract_review":ident("work/queue.ready-handoff/caller-review.json"),"corrected_contract":ident("work/queue.ready-handoff-review/request-review.json"),"actual_completed_scope":["One native PIXL specialist assessed original and revised contracts, art direction, saved criteria and current controlled-fixture delivery.","New future contract and citation corrections reviewed independently; discrepancies resolved with same specialist.","Independent PNG decode, saved image inspection and actual Node source-consumer integration passed.","Exact specialist handoff independently matched fresh focused PLAR continuation and every linked artifact hash.","All "+str(len(baseline))+" baseline consumer files preserved byte-for-byte; completed production and historical acceptance unchanged."],"adoption_scope":"Corrected future proposal only; no retroactive contract replacement or verdict transplant.","unresolved_obligations":h["details"]["future_work"],"production":{"requirements_hash":h["requirements_hash"],"state_hash":h["resume"]["state_hash"],"task_state":"done","candidate":"ready.retained","provider":"pixellab-test","remote_id":"controlled-create-0002","provenance":"Controlled fixture; not upstream art","derived_next":h["next"],"new_generation_performed":False},"verification":checks}
pathlib.Path("HANDOFF-RESULT.json").write_text(json.dumps(result,indent=2)+"\\n",encoding="utf-8")
